-- ==========================================================
-- Supabase (PostgreSQL) Schema & Data for Sarpanch Portal
-- ==========================================================

DROP TABLE IF EXISTS candidates, works, complaints, settings CASCADE;

CREATE TABLE candidates (
  "id" TEXT PRIMARY KEY,
  "name" TEXT NOT NULL,
  "party" TEXT,
  "partyBadge" TEXT,
  "slogan" TEXT,
  "age" INTEGER,
  "education" TEXT,
  "educationDetails" TEXT,
  "village" TEXT,
  "phone" TEXT,
  "ward" TEXT,
  "photo" TEXT,
  "symbol" TEXT,
  "votes" INTEGER DEFAULT 0,
  "bio" TEXT,
  "achievements" TEXT,
  "promises" TEXT
);

CREATE TABLE works (
  "id" INTEGER PRIMARY KEY,
  "title" TEXT NOT NULL,
  "scheme" TEXT,
  "budget" BIGINT DEFAULT 0,
  "spent" BIGINT DEFAULT 0,
  "panchayatShare" BIGINT DEFAULT 0,
  "balance" BIGINT DEFAULT 0,
  "status" TEXT,
  "category" TEXT,
  "length" TEXT,
  "workType" TEXT,
  "contractor" TEXT,
  "startDate" TEXT,
  "endDate" TEXT,
  "progress" INTEGER DEFAULT 0,
  "image" TEXT,
  "description" TEXT
);

CREATE TABLE complaints (
  "id" SERIAL PRIMARY KEY,
  "name" TEXT,
  "phone" TEXT,
  "ward" TEXT,
  "subject" TEXT,
  "message" TEXT,
  "status" TEXT DEFAULT 'लंबित',
  "date" TEXT,
  "reply" TEXT
);

CREATE TABLE settings (
  "key" TEXT PRIMARY KEY,
  "value" TEXT
);

-- Disable RLS for website access
ALTER TABLE candidates DISABLE ROW LEVEL SECURITY;
ALTER TABLE works DISABLE ROW LEVEL SECURITY;
ALTER TABLE complaints DISABLE ROW LEVEL SECURITY;
ALTER TABLE settings DISABLE ROW LEVEL SECURITY;
