INSERT INTO candidates (id, name, party, partyBadge, slogan, age, education, educationDetails, village, phone, ward, photo, symbol, votes, bio, achievements, promises) VALUES ('ramesh-chand', ' आनंद डैला', 'निर्दलीय', 'IND', 'गाँव का विकास, गाँव का साथ', 50, 'हाईस्कूल', 'हाईस्कूल (उ.प्र. बोर्ड)। 25 वर्षों का खेती-किसानी व ग्राम सेवा अनुभव।', ' काकोड़ा', '+91 9413366025', 'वार्ड ', '/uploads/candidates/cand-1791011220171.jpeg', 'किसान ट्रैक्टर', 3, 'एक ईमानदार किसान, जो बिना किसी पार्टी के भेदभाव के पूरे गाँव के विकास के लिए हर समय ग्रामीणों के सुख-दुख में साथ खड़ा रहता है।', '["नहर की मरम्मत कराकर टेल तक सिंचाई का पानी पहुँचाया","गाँव के आपसी विवादों को चौपाल में भाईचारे से सुलझाया"]', '["पारदर्शी बजट प्रणाली: हर महीने ग्राम सभा में खर्च का सार्वजनिक हिसाब","गौशाला का निर्माण एवं आवारा पशुओं से फसलों की सुरक्षा","किसान भाइयों के लिए मुफ्त मिट्टी जांच और फसल बीमा शिविर"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO candidates (id, name, party, partyBadge, slogan, age, education, educationDetails, village, phone, ward, photo, symbol, votes, bio, achievements, promises) VALUES ('mahesh-kumar', ' यश (लवली) डैला', 'कांग्रेस', 'INC', 'शिक्षा, स्वास्थ्य, रोज़गार', 27, 'एम.ए., बी.एड.', 'एम.ए. (इतिहास) एवं बी.एड., उत्तर प्रदेश विश्वविद्यालय।', ' काकोड़ा', '+91 9461599994', 'वार्ड 2', '/uploads/candidates/cand-1791011408130.jpeg', 'हाथ', 2, 'शिक्षा के क्षेत्र में 12 वर्षों का अनुभव। गाँव के युवाओं को उच्च शिक्षा, खेल सुविधाएं और रोजगार के बेहतर अवसर दिलाने के लिए समर्पित।', '["गाँव में निःशुल्क प्रतियोगी परीक्षा कोचिंग सेंटर की स्थापना","30+ मेधावी युवाओं को सरकारी नौकरी में सफलता दिलवाई","हरियाली अभियान के तहत 5,000+ छायादार पौधे रोपे"]', '["गाँव के स्कूलों में आधुनिक स्मार्ट क्लासेस और खेल मैदान का विकास","किसान सहायता केंद्र की स्थापना और खाद-बीज की सुगम उपलब्धता","गाँव में महिला सुरक्षा हेतु सीसीटीवी कैमरे व स्ट्रीट लाइटें"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO candidates (id, name, party, partyBadge, slogan, age, education, educationDetails, village, phone, ward, photo, symbol, votes, bio, achievements, promises) VALUES ('cand-1791020183984', 'सतवीर ', 'BJP', 'IND', '', 60, '', '', 'काकोडा', '', 'वार्ड 1', '/uploads/candidates/cand-1791020222389.png', 'कलम', 1, '', '[]', '[]') ON CONFLICT (id) DO NOTHING;
INSERT INTO candidates (id, name, party, partyBadge, slogan, age, education, educationDetails, village, phone, ward, photo, symbol, votes, bio, achievements, promises) VALUES ('seema-devi', ' संदीप डैला', 'कांग्रेस', 'INC', ' बेहतर गाँव', 45, 'इंटरमीडिएट', 'इंटरमीडिएट (कला वर्ग), राजकीय कन्या इंटर कॉलेज।', ' काकोड़ा', '+91 8696190666', 'वार्ड ', '/uploads/candidates/cand-1791017137694.jpeg', 'कप-प्लेट', 0, '', '[]', '["गाँव  के लिए अलग सामुदायिक व कौशल केंद्र","बुजुर्गों व विधवा माताओं को घर बैठे समय पर पेंशन वितरण","गाँव के हर घर में व्यक्तिगत शौचालय और कचरा प्रबंधन"]') ON CONFLICT (id) DO NOTHING;
INSERT INTO works (id, title, scheme, budget, spent, panchayatShare, balance, status, category, length, workType, contractor, startDate, endDate, progress, image, description) VALUES (1, 'आँगनबाड़ी द्वितीय के पास बने सार्व बोरवेल सूखने पर नया बोरिंग बनाना, नई डिलीवरी पाइपलाइन डालना व सामान शिफ्ट करना आदि कार्य काकोड़ा', '15वाँ वित्त आयोग (XVFC) - पंचायती राज विभाग', 600000, 419482, 600000, 180518, 'पूर्ण', 'स्वास्थ्य एवं पेयजल', 'नया बोरवेल + डिलीवरी पाइपलाइन (100% पूर्ण)', 'जल उपचार संयंत्र एवं बोरवेल निर्माण', 'शुभम निर्माण कंपनी एवं एम. के. शर्मा #38 एसोसिएट्स', '12 सितम्बर 2024', '06 जनवरी 2025', 100, '/uploads/works/borewell-kakoda-cropped.png', 'आँगनबाड़ी द्वितीय के पास बने सार्वजनिक बोरवेल सूखने पर ग्रामीणों एवं बच्चों को स्वच्छ पेयजल उपलब्ध कराने हेतु 15वें वित्त आयोग से ₹6,00,000 की प्रशासनिक एवं वित्तीय स्वीकृति के अंतर्गत नया बोरिंग कराया गया, नई हैवी डिलीवरी पाइपलाइन डाली गई, मोटर व उपकरण शिफ्ट कर जल उपचार संयंत्र (वाटर स्टोरेज व सप्लाई) का निर्माण कार्य 100% संतोषजनक रूप से पूर्ण किया गया। ई-ग्राम स्वराज पोर्टल पर वाउचर पी/17 (₹4,06,898) व वाउचर पी/18 (₹12,584) का भुगतान प्रमाणित है।') ON CONFLICT (id) DO NOTHING;
INSERT INTO works (id, title, scheme, budget, spent, panchayatShare, balance, status, category, length, workType, contractor, startDate, endDate, progress, image, description) VALUES (2, 'रामदेव भार्गव के पास बनी पानी की टंकी को ऊँचा उठाने का निर्माण कार्य काकोड़ा', '15वाँ वित्त आयोग (XVFC)', 100000, 94633, 100000, 5367, 'पूर्ण', 'पेयजल एवं स्वच्छता', 'पानी टंकी ऊंचाई वृद्धि एवं सुदृढ़ीकरण', 'पेयजल टंकी निर्माण', 'शुभम निर्माण कंपनी', '01 अक्टूबर 2024', '06 जनवरी 2025', 100, '/uploads/works/voucher-tanki.png', 'पेयजल वितरण दबाव बेहतर करने के उद्देश्य से रामदेव भार्गव के घर के पास बनी सार्वजनिक पेयजल टंकी को आवश्यकतानुसार ऊँचा उठाने व मजबूती प्रदान करने का पक्का निर्माण कार्य 15वें वित्त आयोग से पूर्ण किया गया। वाउचर पी/19 के तहत ₹94,633 का भुगतान प्रमाणित है।') ON CONFLICT (id) DO NOTHING;
INSERT INTO works (id, title, scheme, budget, spent, panchayatShare, balance, status, category, length, workType, contractor, startDate, endDate, progress, image, description) VALUES (3, 'ख्यालों की ढाणी में सार्वजनिक धर्मशाला में कूप एवं मोटर मरम्मत कार्य', '15वाँ वित्त आयोग (XVFC)', 40000, 38800, 40000, 1200, 'पूर्ण', 'पेयजल एवं सामुदायिक सुविधा', 'मोटर पंप मरम्मत एवं कूप संधारण', 'मरम्मत एवं संधारण कार्य', 'शुभम निर्माण कंपनी', '01 फरवरी 2026', '30 मार्च 2026', 100, '/uploads/works/voucher-repair.png', 'ख्यालों की ढाणी स्थित सार्वजनिक धर्मशाला में ग्रामीणों व यात्रियों के लिए पेयजल कूप की सफाई, समर्सिबल मोटर की मरम्मत, केबलिंग एवं टेस्टिंग का कार्य 15वें वित्त आयोग योजनांतर्गत पूर्ण किया गया। वाउचर पी/18 के तहत ₹38,800 का भुगतान हुआ।') ON CONFLICT (id) DO NOTHING;
INSERT INTO works (id, title, scheme, budget, spent, panchayatShare, balance, status, category, length, workType, contractor, startDate, endDate, progress, image, description) VALUES (4, 'आँगनबाड़ी प्रथम के कूप एवं जल व्यवस्था मरम्मत कार्य', '15वाँ वित्त आयोग (XVFC)', 30000, 28896, 30000, 1104, 'पूर्ण', 'स्वास्थ्य एवं आँगनबाड़ी सुविधा', 'कूप मरम्मत व पाइपलाइन दुरुस्तीकरण', 'मरम्मत एवं संधारण कार्य', 'शुभम निर्माण कंपनी', '10 फरवरी 2026', '30 मार्च 2026', 100, '/uploads/works/voucher-repair.png', 'आँगनबाड़ी केंद्र 1 में बच्चों और पोषण कार्यकर्ताओं के लिए स्वच्छ जल उपलब्धता सुनिश्चित करने हेतु कूप मरम्मत, पाइप फिटिंग एवं वाटर सप्लाई रिपेयर कार्य 15वें वित्त आयोग से पूर्ण कराया गया। वाउचर पी/17 के तहत ₹28,896 का भुगतान दर्ज है।') ON CONFLICT (id) DO NOTHING;
INSERT INTO works (id, title, scheme, budget, spent, panchayatShare, balance, status, category, length, workType, contractor, startDate, endDate, progress, image, description) VALUES (5, 'मुख्य गाँव में सोलर स्ट्रीट लाइट लगाना', 'ग्राम ज्योति योजना (15वाँ वित्त आयोग)', 1000000, 875000, 100000, 125000, 'पूर्ण', 'बिजली', '60 सोलर एलईडी लाइट्स', 'विद्युतीकरण', 'सनलाइट सोलर प्रा. लि.', '05 जुलाई 2023', '28 सितम्बर 2023', 100, 'https://images.unsplash.com/photo-1509391365360-2e959784a276?w=800&h=450&fit=crop', 'गाँव के सभी मुख्य मार्गों, चौराहों और अंधेरे मोड़ों पर ऑटोमैटिक सोलर एलईडी लाइट्स की स्थापना।') ON CONFLICT (id) DO NOTHING;
INSERT INTO works (id, title, scheme, budget, spent, panchayatShare, balance, status, category, length, workType, contractor, startDate, endDate, progress, image, description) VALUES (6, 'तालाब खुदाई व अमृत सरोवर विकास', 'मनरेगा अमृत सरोवर मिशन', 1800000, 1500000, 100000, 300000, 'पूर्ण', 'पर्यावरण', '2 एकड़ क्षेत्र', 'जल संरक्षण', 'ग्राम पंचायत समिति काकोड़ा', '12 फरवरी 2023', '12 जनवरी 2024', 100, 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800&h=450&fit=crop', 'गाँव के ऐतिहासिक तालाब की खुदाई, पक्के घाटों का निर्माण, चारों ओर पेड़-पौधे और टहलने हेतु ट्रैक।') ON CONFLICT (id) DO NOTHING;
