INSERT INTO works (id, title, scheme, budget, spent, panchayatShare, balance, status, category, length, workType, contractor, startDate, endDate, progress, image, description) VALUES (8, 'श्याम मन्दिर से लेकर महेन्द्र सिंह के घर के पास सार्व सिंगल फेस कुप की ओर इन्टर लॉक निर्माण कार्य रघुनाथपुरा', 'राज्य वित्त आयोग (पंचम)', 500000, 500000, 50000, 0, 'पूर्ण', 'सड़क एवं नाली निर्माण', '0.3 - 0.8 किमी', 'इंटरलॉक एवं सिविल निर्माण', 'ग्राम पंचायत काकोड़ा', '26 अक्टूबर 2017', '15 मार्च 2018', 100, 'https://images.unsplash.com/photo-1545459720-aac8509eb02c?w=800&h=450&fit=crop', 'ग्राम रघुनाथपुरा में श्याम मन्दिर से लेकर महेन्द्र सिंह के घर के पास स्थित सार्वजनिक सिंगल फेस कूप की ओर मजबूत इंटरलॉक सड़क निर्माण कार्य राज्य वित्त आयोग पंचम द्वारा पूर्ण किया गया।') ON CONFLICT (id) DO NOTHING;
INSERT INTO works (id, title, scheme, budget, spent, panchayatShare, balance, status, category, length, workType, contractor, startDate, endDate, progress, image, description) VALUES (9, 'गॉव रघुनाथपुरा में सांवरमल जोगीड़ के घर से काशीराम के घर की ओर सी.सी. सड़क निर्माण', 'राज्य वित्त आयोग (पंचम)', 400000, 400000, 40000, 0, 'पूर्ण', 'सड़क एवं नाली निर्माण', '0.3 - 0.8 किमी', 'इंटरलॉक एवं सिविल निर्माण', 'ग्राम पंचायत काकोड़ा', '11 अप्रैल 2018', '30 जून 2018', 100, 'https://images.unsplash.com/photo-1519817650390-64a93db51149?w=800&h=450&fit=crop', 'रघुनाथपुरा गाँव में आवागमन को सुगम बनाने हेतु सांवरमल जोगीड़ के घर से काशीराम के घर की ओर सी.सी. सड़क का निर्माण कार्य राज्य वित्त आयोग पंचम योजनान्तर्गत सम्पन्न हुआ।') ON CONFLICT (id) DO NOTHING;
