INSERT INTO settings (key, value) VALUES ('duties', '[{"num":"1","title":"बुनियादी सुविधाएं","icon":"fa-road","color":"#0ea5e9","summary":"सड़क, पानी, बिजली, नाली की पक्की व्यवस्था","details":"हर घर तक पक्की सड़क, 24 घंटे बिजली, शुद्ध पेयजल और भूमिगत जल निकासी की व्यवस्था करना।"},{"num":"2","title":"शिक्षा और स्वास्थ्य","icon":"fa-heart-pulse","color":"#10b981","summary":"विद्यालयों का सुधार, स्वास्थ्य केंद्र और टीकाकरण","details":"गाँव के बच्चों को गुणवत्तापूर्ण प्राथमिक व माध्यमिक शिक्षा और स्वास्थ्य केंद्र में डॉक्टर व दवाइयों की उपलब्धता।"},{"num":"3","title":"कृषि और रोजगार","icon":"fa-seedling","color":"#f59e0b","summary":"किसानों के लिए सरकारी योजनाएं, रोजगार के अवसर","details":"किसान सम्मान निधि, आधुनिक कृषि उपकरण, बीज सब्सिडी और मनरेगा में पारदर्शी व समय पर मजदूरी भुगतान।"},{"num":"4","title":"सामाजिक न्याय","icon":"fa-scale-balanced","color":"#8b5cf6","summary":"सभी वर्गों के लिए समान अवसर, महिला/बुजुर्ग योजनाएं","details":"महिला सुरक्षा व स्वावलंबन, वृद्धजन व दिव्यांगजन पेंशन, राशन कार्ड व आवास योजनाओं में निष्पक्षता।"},{"num":"5","title":"डिजिटल और पारदर्शिता","icon":"fa-laptop","color":"#06b6d4","summary":"ऑनलाइन शिकायतें, राशन, पेंशन, फंड का खुला हिसाब","details":"पंचायत निधि के हर पैसे का सार्वजनिक ब्यौरा और सरकारी योजनाओं के आवेदन हेतु ग्राम सीएससी सेवा केंद्र।"}]') ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
